using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class VerifyCollisionProxies {
 static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B4_DeskAndCollision/"));
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");string original=SceneManager.GetActiveScene().path;var sources=JArray.Parse(File.ReadAllText(H+"ghost_candidates.json")).ToDictionary(j=>(string)j["asset"]);var models=JArray.Parse(File.ReadAllText(H+"collision_models.json"));var log=new List<object>();var temp=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);try{var ps=temp.GetPhysicsScene();var hits=new Collider[4];foreach(var row in models){var m=AssetDatabase.LoadAllAssetsAtPath((string)row["asset"]).OfType<Mesh>().Single();var old=AssetDatabase.LoadAllAssetsAtPath((string)row["original"]).OfType<Mesh>().Single();var g=new GameObject("CollisionProxyProbe"){hideFlags=HideFlags.HideAndDontSave};SceneManager.MoveGameObjectToScene(g,temp);g.transform.position=new Vector3(0,10000,0);g.AddComponent<MeshCollider>().sharedMesh=m;Physics.SyncTransforms();var source=sources[(string)row["original"]];int blocked=0,wideResidual=0;foreach(var p in source["points"]){float x=(float)p[0],z=(float)p[2];if(ps.OverlapCapsule(new Vector3(x,10000.38f,z),new Vector3(x,10001.48f,z),.28f,hits,~0,QueryTriggerInteraction.Ignore)>0){blocked++;if(ps.OverlapCapsule(new Vector3(x,10000.38f,z),new Vector3(x,10001.48f,z),.26f,hits,~0,QueryTriggerInteraction.Ignore)>0)wideResidual++;}}var v=m.vertices;var ix=m.triangles;int deg=0;for(int i=0;i<ix.Length;i+=3)if(Vector3.Cross(v[ix[i+1]]-v[ix[i]],v[ix[i+2]]-v[ix[i]]).sqrMagnitude<1e-16f)deg++;log.Add(new{asset=(string)row["asset"],triangles=ix.Length/3,renderTriangles=old.triangles.Length/3,emptyBefore=(int)source["empty"],emptyStillBlocked=blocked,beyond2cmBevel=wideResidual,boundsCenterDelta=Vector3.Distance(old.bounds.center,m.bounds.center),boundsSizeDelta=Vector3.Distance(old.bounds.size,m.bounds.size),degenerate=deg});UnityEngine.Object.DestroyImmediate(g);}}finally{EditorSceneManager.CloseScene(temp,true);EditorSceneManager.OpenScene(original);}File.WriteAllText(H+"proxies_verification.json",JsonConvert.SerializeObject(log,Formatting.Indented));return log;}
}
